    "hi": ("Hindi", "भारत"),
    "te": ("Telugu", "భారతదేశం"),
    "mai": ("Maithili", "भारत"),
    "mr": ("Marathi", "भारत"),
}


def get(url: str) -> requests.Response:
    return requests.get(url, headers={"User-Agent": USER_AGENT}, timeout=(8, 30))


def absolutize_links(soup: BeautifulSoup, lang: str) -> None:
    base = f"https://{lang}.wikipedia.org/wiki/"
    for tag in soup.find_all(["a", "img", "source"]):
        attr = "href" if tag.name == "a" else "src"
        value = tag.get(attr)
        if not value:
            continue
        if value.startswith("//"):
            tag[attr] = "https:" + value
        elif value.startswith("./"):
            tag[attr] = urljoin(base, value[2:])
        elif value.startswith("/"):
            tag[attr] = urljoin(f"https://{lang}.wikipedia.org", value)


def strip_only_technical_noise(node: BeautifulSoup, soup: BeautifulSoup) -> None:
    for tag in node(["script", "style", "meta"]):
        tag.decompose()
    for tag in node.find_all("link"):
        rel = " ".join(tag.get("rel") or [])
        href = tag.get("href") or ""
        if "mw:PageProp/Category" in rel and href:
            tag.replace_with(soup.new_string(f"\nCategory: {href}\n"))

"""
Stage 9 — Decontamination (the eval firewall).

The firewall between the data we train on and the material we judge ourselves with.
We fingerprint the held-out evaluation set, scan every training document for overlap
against those fingerprints, remove any training doc that carries a piece of a test
item, and plant a canary string so a later leak is detectable.

Fingerprints are sets of word 8-grams. A training doc is contaminated if it shares
at least one 8-gram with any eval item (n-gram containment, the standard test).
"""
# 13-word n-grams (the GPT-3 contamination convention). Long enough that an
# overlap means a genuine shared passage, not two docs happening to reuse a phrase.
NGRAM = 13
CANARY = "CANARY::era-v5-session4::do-not-train::7f3a9c21"


def _ngrams(tokens, n=NGRAM):
    if len(tokens) < n:
        return {" ".join(tokens)} if tokens else set()
    return {" ".join(tokens[i:i + n]) for i in range(len(tokens) - n + 1)}


def build_fingerprints(eval_token_lists):
    """Union of all eval-item n-grams -> one fingerprint set."""
    fp = set()
    for toks in eval_token_lists:
        fp |= _ngrams(toks)
    return fp


def is_contaminated(tokens, fingerprints):
    if CANARY in " ".join(tokens):
        return True
    return not _ngrams(tokens).isdisjoint(fingerprints)


def new_stats():
    return {
        "eval_items": 0,
        "fingerprint_ngrams": 0,
        "docs_scanned": 0,
        "contaminated_removed": 0,
        "canary_planted": 0,
        "canary_detected": 0,
    }

"""
Stage 10 — Reproducibility & the manifest.

A clean corpus is only trustworthy if we can say exactly where every part of it came
from and reproduce it on demand. Two ideas:

  Reproducibility — the pipeline is deterministic, so the same input gives the same
                    output and the same identifiers. Identifiers are built from the
                    CONTENT (a hash) rather than a running counter, and the content
                    hash is computed AFTER cleaning, so it reflects the cleaned text.

  Provenance      — every shard carries a manifest recording its source, license,
                    contributor, the exact cleaning script that produced it, a content
                    hash, the token count, and the language breakdown. No shard enters
                    the corpus without one; an unknown/unsafe license blocks the shard.
"""
import hashlib
import os

SAFE_LICENSES = {"MIT", "Apache-2.0", "CC-BY-4.0", "CC-BY-SA-4.0", "CC0-1.0"}


def sha256(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def cleaning_script_hash(pipeline_dir):
    """Hash every stage module so the manifest pins the exact cleaning code."""
    h = hashlib.sha256()
    for fn in sorted(os.listdir(pipeline_dir)):
        if fn.endswith(".py"):
            with open(os.path.join(pipeline_dir, fn), "rb") as f:
                h.update(fn.encode())
                h.update(f.read())
    return h.hexdigest()


def doc_id(cleaned_text):
    """Deterministic content-addressed id (not a running counter)."""
    return "sha256:" + sha256(cleaned_text)[:16]


